<script setup>
import {onMounted,ref} from 'vue';import {useAdminAuthStore} from '../stores/adminAuth.js';import {fetchPlatformOperations} from '../services/adminSession.js'
const auth=useAdminAuthStore(),data=ref({webhooks:[],audits:[]}),error=ref('');const date=v=>v?new Intl.DateTimeFormat('tr-TR',{dateStyle:'short',timeStyle:'short'}).format(new Date(v)):'—'
onMounted(async()=>{try{data.value=await fetchPlatformOperations({apiUrl:import.meta.env.VITE_API_URL||'',accessToken:auth.session.access_token})}catch{error.value='Operasyon kayıtları yüklenemedi.'}})
</script>
<template><main class="dashboard"><header><div><div class="eyebrow">GÖZLEMLENEBİLİRLİK</div><h1>Operasyon kayıtları</h1></div><RouterLink class="button-link secondary" to="/dashboard">Genel duruma dön</RouterLink></header><p v-if="error" class="notice">{{error}}</p><h2>Webhook olayları</h2><section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Konu</th><th>Mağaza</th><th>Durum</th><th>Deneme</th><th>Son hata</th><th>Alınma</th></tr></thead><tbody><tr v-for="event in data.webhooks" :key="event.id"><td>{{event.topic}}</td><td>{{event.storeName||'—'}}</td><td>{{event.status}}</td><td>{{event.attemptCount}}</td><td>{{event.errorMessage||'—'}}</td><td>{{date(event.receivedAt)}}</td></tr><tr v-if="!data.webhooks.length"><td colspan="6" class="empty">Webhook olayı yok.</td></tr></tbody></table></div></section><h2>Audit kayıtları</h2><section class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>İşlem</th><th>Aktör</th><th>Workspace</th><th>Hedef</th><th>Tarih</th></tr></thead><tbody><tr v-for="event in data.audits" :key="event.id"><td>{{event.action}}</td><td>{{event.actorEmail||'sistem'}}</td><td>{{event.workspaceName||'—'}}</td><td>{{event.targetType}} · {{event.targetId||'—'}}</td><td>{{date(event.createdAt)}}</td></tr></tbody></table></div></section></main></template>
